svg.script:
(function(){
  function findInputs(){
    var ids = ["fs-show-regions","fs-show-id","fs-show-name"];
    var out = {};
    for (var i = 0; i < ids.length; i++) {
      var id = ids[i];
      var el = document.getElementById(id);
      if (!el && document.querySelector) el = document.querySelector("#" + id);
      if (!el) {
        var fos = document.getElementsByTagName("foreignObject");
        for (var f = 0; f < fos.length && !el; f++) {
          var nodes = fos[f].getElementsByTagName("*");
          for (var n = 0; n < nodes.length; n++) {
            if (nodes[n].id === id) { el = nodes[n]; break; }
          }
        }
      }
      out[id] = el;
    }
    return out;
  }
  function apply(){
    var svg = document.documentElement;
    var inputs = findInputs();
    function chk(name){ return inputs[name] ? !!inputs[name].checked : true; }
    var showRegions = chk("fs-show-regions");
    var showId      = chk("fs-show-id");
    var showName    = chk("fs-show-name");
    function setAll(sel, visible){
      var list = svg.querySelectorAll(sel);
      for (var i = 0; i < list.length; i++) {
        list[i].style.display = visible ? "" : "none";
      }
    }
    setAll('[data-role="face"]', showRegions);
    setAll('[data-role="id"]',   showRegions && showId);
    setAll('[data-role="name"]', showRegions && showName);
  }
  function boot(){
    var inputs = findInputs();
    var names = ["fs-show-regions","fs-show-id","fs-show-name"];
    for (var i = 0; i < names.length; i++) {
      var el = inputs[names[i]];
      if (el) el.addEventListener("change", apply);
    }
    apply();
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else { setTimeout(boot, 0); }
})();
